1209	\begin{definition}[Expanded observables]
1210		\label{def:expanded-observables}
1211		\lean{MIPStarRE.QPBT.ProjectiveSetting.expObs}
1212		\leanok
1213		\uses{def:strategy-observables, def:expanded-state, lem:twisted-commutation}
1214		For all $W \in \{X,Z\}$, $r \in \F_q$, and $u \in \F_q^m$, define the
1215		observable
1216		\begin{equation}\label{eq:lc-23}
1217			\hat{W}^r(u) \,=\, W^r(u) \ot \tau^W(r \cdot \mathrm{ind}_m(u))\,,
1218		\end{equation}
1219		where $W^r(u)$ is the strategy observable of~\eqref{eq:qld-strat-obs}
1220		and $\tau^W(r \cdot \mathrm{ind}_m(u))$ is the generalized Pauli
1221		observable acting on $(\C^q)^{\ot M}$, introduced in
1222		Chapter~\ref{chap:qpbt-algebra}
1223		(see Lemma~\ref{lem:twisted-commutation}). As a product
1224		of two observables with eigenvalues $\pm 1$ acting on disjoint
1225		registers, $\hat{W}^r(u)$ is itself an observable with eigenvalues
1226		$\pm 1$. If $W^r(u)$ is viewed as acting on register $\mathsf{A}$, then
1227		$\hat{W}^r(u)$ is viewed as acting on registers
1228		$\mathsf{A}\mathsf{A}'$, with the $\tau^W$ factor acting on
1229		$\mathsf{A}'$. The registers are generally indicated by subscripts, as
1230		in $(\hat{W}^r(u))_{\mathsf{A}\mathsf{A}'}$ or
1231		$(\hat{W}^r(u))_{\mathsf{B}\mathsf{A}''}$, the latter having the
1232		strategy factor on $\mathsf{B}$ and the Pauli factor on
1233		$\mathsf{A}''$.
1234	\end{definition}
